import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/Home.css';

const Home = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const anchorLinks = document.querySelectorAll('a[href^="#"]');

    anchorLinks.forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });

    const header = document.querySelector('header');
    const handleScroll = () => {
      if (window.scrollY > 100) {
        header.style.background = 'rgba(99, 102, 241, 0.98)';
        header.style.boxShadow = '0 4px 25px rgba(99, 102, 241, 0.4)';
      } else {
        header.style.background = 'rgba(99, 102, 241, 0.95)';
        header.style.boxShadow = '0 4px 20px rgba(99, 102, 241, 0.3)';
      }
    };

    window.addEventListener('scroll', handleScroll);

    return () => {
      anchorLinks.forEach(anchor => {
        anchor.removeEventListener('click', () => {});
      });
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <>
      <header>
        <nav className="container">
          <a href="#" className="logo">
            <div className="logo-icon">M+</div>
            MEDIVAULT
          </a>
          <ul className="nav-links">
            <li><a href="#home">Home</a></li>
            <li><a href="#features">Features</a></li>
            <li><a href="#contact">Contact</a></li>
          </ul>
          <div className="auth-buttons">
            <button className="login-btn" onClick={() => navigate('/login')}>Login</button>
            <button className="signup-btn" onClick={() => navigate('/register')}><span>Sign Up</span></button>
          </div>
        </nav>
      </header>

      <section className="hero" id="home">
        <div className="floating-elements">
          <div className="floating-element"></div>
          <div className="floating-element"></div>
          <div className="floating-element"></div>
        </div>
        <div className="container">
          <div className="hero-content">
            <h1>Secure Your Medical Records in One Digital Vault</h1>
            <p>Store, organize, and access your medical records with military-grade security and AI-powered organization.</p>
            <div className="hero-buttons">
              <button className="primary-btn" onClick={() => navigate('/register')}>Start Free Trial</button>
              <a href="#features" className="secondary-btn">Learn More</a>
            </div>
          </div>
        </div>
      </section>

      <section className="features" id="features">
        <div className="container">
          <div className="section-header">
            <h2>Why Choose MEDIVAULT?</h2>
            <p>Revolutionary features designed to transform your healthcare document management experience</p>
          </div>
          <div className="features-grid">
            <div className="feature-card">
              <div className="feature-icon">🔐</div>
              <h3>Bank-Level Security</h3>
              <p>Protected with 256-bit encryption, multi-factor authentication, and HIPAA compliance.</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">📱</div>
              <h3>Access Anywhere</h3>
              <p>Manage records from any device, anytime, anywhere in the world.</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">🤖</div>
              <h3>AI-Powered Organization</h3>
              <p>Automatic categorization, tagging, and instant document search.</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">🔄</div>
              <h3>Seamless Integration</h3>
              <p>Connect with providers, labs, and hospitals for auto updates.</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">📊</div>
              <h3>Health Analytics</h3>
              <p>Personalized insights and health trends for smarter care decisions.</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">👨‍👩‍👧‍👦</div>
              <h3>Family Management</h3>
              <p>Manage records for your family with permissions and emergency access.</p>
            </div>
          </div>
        </div>
      </section>

      <section className="cta-section">
        <div className="container">
          <h2>Ready to Transform Your Healthcare Experience?</h2>
          <p>Join thousands who trust MEDIVAULT. Start your secure digital health journey today.</p>
          <div className="cta-buttons">
            <button className="primary-btn" onClick={() => navigate('/register')}>Get Started Free</button>
          </div>
        </div>
      </section>
    </>
  );
};

export default Home;
